import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded optimizer for character-level serialized prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert one scalar to evaluator text, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if not hasattr(missing, "__len__") and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute an exact common-prefix length using binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute ideal Trie reuse as LCP lengths of sorted adjacent row strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested merge groups contiguous while preserving their proposed order."""
        if not col_merge:
            return list(order)

        position = {column: i for i, column in enumerate(order)}
        owners = {}
        claimed = set()

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=position.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert integer positions into a valid column permutation respecting merges."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: i for i, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize each row using its assigned row-specific column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    @staticmethod
    def _pair_mass(values):
        """Measure length-weighted repeated-value pairs in a sequence of strings."""
        counts = Counter(values)
        return sum(
            len(value) * count * (count - 1)
            for value, count in counts.items()
        )

    def _global_candidates(self, text, columns, col_merge):
        """Build whole-value and partial-prefix frequency-ranked global layouts."""
        rows = len(text)
        width = len(columns)

        whole_mass = [0] * width
        prefix_mass = [0] * width
        distinct = [0] * width
        prefix_distinct = [0] * width

        for column in range(width):
            values = [text[row][column] for row in range(rows)]
            counts = Counter(values)

            distinct[column] = len(counts)
            whole_mass[column] = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )

            prefixes = Counter()
            for value, count in counts.items():
                limit = min(8, len(value))
                for length in range(1, limit + 1):
                    prefixes[value[:length]] += count

            prefix_distinct[column] = len(prefixes)
            prefix_mass[column] = sum(
                len(prefix) * count * (count - 1)
                for prefix, count in prefixes.items()
            )

        whole_order = sorted(
            range(width),
            key=lambda column: (
                -whole_mass[column],
                distinct[column],
                column,
            ),
        )

        prefix_order = sorted(
            range(width),
            key=lambda column: (
                -prefix_mass[column],
                prefix_distinct[column],
                -whole_mass[column],
                column,
            ),
        )

        return [
            self._normalize(columns, whole_order, col_merge),
            self._normalize(columns, prefix_order, col_merge),
        ], whole_order, whole_mass

    def _conditional_bank(
        self,
        text,
        columns,
        col_merge,
        base_order,
        whole_mass,
    ):
        """Build one anchor-value bank with a separately ranked suffix per group."""
        rows = len(text)
        width = len(columns)

        fallback = self._normalize(columns, base_order, col_merge)
        result = [fallback[:] for _ in range(rows)]

        if rows < 2 or width < 2:
            return result

        anchor_pool = base_order[:min(6, width)]
        anchor = max(
            anchor_pool,
            key=lambda column: (whole_mass[column], -column),
        )

        value_to_group = {}
        groups = []

        for row in range(rows):
            value = text[row][anchor]
            group = value_to_group.get(value)
            if group is None:
                group = len(groups)
                value_to_group[value] = group
                groups.append([])
            groups[group].append(row)

        suffix_candidates = [
            column for column in base_order
            if column != anchor
        ][:min(32, width - 1)]

        suffix_set = set(suffix_candidates)
        tail = [
            column for column in base_order
            if column != anchor and column not in suffix_set
        ]

        rank_position = {
            column: position
            for position, column in enumerate(base_order)
        }

        global_order = self._normalize(
            columns,
            [anchor] + suffix_candidates + tail,
            col_merge,
        )

        for members in groups:
            if len(members) < 2:
                for row in members:
                    result[row] = global_order[:]
                continue

            ranked = []
            for column in suffix_candidates:
                counts = Counter(text[row][column] for row in members)
                mass = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((
                    -mass,
                    rank_position[column],
                    column,
                ))

            ranked.sort()
            suffix = [item[2] for item in ranked] + tail

            local_order = self._normalize(
                columns,
                [anchor] + suffix,
                col_merge,
            )

            for row in members:
                result[row] = local_order[:]

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded layout by exact serialized Trie reuse."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_orders, base_order, whole_mass = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_orders:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        conditional_orders = self._conditional_bank(
            text,
            columns,
            col_merge,
            base_order,
            whole_mass,
        )
        conditional_serialized = self._serialize(
            text,
            conditional_orders,
        )
        candidates.append((
            self._reuse(conditional_serialized),
            conditional_orders,
            conditional_serialized,
        ))

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]

        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )

        return result, orderings

